import itertools

def calculate_sumset_size(A):
    # Calculate S = {a + b | a, b in A, a <= b}
    sums = set()
    N = len(A)
    for i in range(N):
        for j in range(i, N):
            sums.add(A[i] + A[j])
    return len(sums)

# Case 1: Deviation at the start (t1-t0 = 1)
# A1 = {0, 1, 3, 5, ..., 171}
A1 = [0]
# t_i = 2(i-1) + 1 for i >= 1. The sequence has 86 terms from i=1 to i=86.
for i in range(1, 87):
    # The elements are 1, 3, 5, ..., 171.
    # We can generate them as 2*j - 1 for j=1 to 86.
    A1.append(2 * i - 1) 

print(f"Size of sumset for A1: {calculate_sumset_size(A1)}")

